CREATE TABLE official_catalog_seed(user_id TEXT PRIMARY KEY REFERENCES member(user_id),created_at INTEGER NOT NULL);
CREATE TRIGGER official_catalog_seed_singleton BEFORE INSERT ON official_catalog_seed WHEN (SELECT count(*) FROM official_catalog_seed)>=1 BEGIN SELECT RAISE(ABORT,'official_seed_singleton'); END;
CREATE TRIGGER official_catalog_seed_identity BEFORE UPDATE OF user_id ON official_catalog_seed BEGIN SELECT RAISE(ABORT,'official_seed_immutable'); END;
DROP TRIGGER submission_admission;
CREATE TRIGGER submission_admission BEFORE INSERT ON asset_version WHEN NOT EXISTS(SELECT 1 FROM asset_version WHERE id=NEW.id) AND ((EXISTS(SELECT 1 FROM official_catalog_seed s WHERE s.user_id=NEW.contributor_id) AND (SELECT count(*) FROM asset_version WHERE contributor_id=NEW.contributor_id AND state NOT IN ('published','withdrawn','rejected'))>=144) OR (NOT EXISTS(SELECT 1 FROM official_catalog_seed s WHERE s.user_id=NEW.contributor_id) AND ((SELECT count(*) FROM asset_version v WHERE v.state NOT IN ('published','withdrawn','rejected') AND NOT EXISTS(SELECT 1 FROM official_catalog_seed s WHERE s.user_id=v.contributor_id))>=100 OR (SELECT count(*) FROM asset_version WHERE contributor_id=NEW.contributor_id AND state NOT IN ('published','withdrawn','rejected'))>=10))) BEGIN SELECT RAISE(ABORT,'submission_budget_exhausted'); END;
